using FastEndpoints;using MediatR;using F=OrderFlow.Inventory.Application.Inventory.InventoryFeatures;namespace OrderFlow.Inventory.Api.Endpoints;public static class InventoryEndpoints
{public sealed class WarehouseReq{public string Name{get;set;}=string.Empty;public string Location{get;set;}=string.Empty;}public class StockReq{public Guid ProductId{get;set;}public Guid WarehouseId{get;set;}public string Sku{get;set;}=string.Empty;public int Quantity{get;set;}}public sealed class ReserveReq:StockReq{public Guid OrderId{get;set;}public Guid ReservationId{get;set;}}public sealed class IdReq{public Guid Id{get;set;}}
public sealed class CreateWarehouse(ISender s):Endpoint<WarehouseReq,F.WarehouseDto>{public override void Configure(){Post("/api/warehouses");AllowAnonymous();}public override async Task HandleAsync(WarehouseReq r,CancellationToken ct)=>await Send.ResponseAsync(await s.Send(new F.CreateWarehouse(r.Name,r.Location),ct),201,ct);}public sealed class GetWarehouses(ISender s):EndpointWithoutRequest<IReadOnlyList<F.WarehouseDto>>{public override void Configure(){Get("/api/warehouses");AllowAnonymous();}public override async Task HandleAsync(CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.GetWarehouses(),ct),ct);}
public sealed class CreateStock(ISender s):Endpoint<StockReq,F.StockDto>{public override void Configure(){Post("/api/stock-items");AllowAnonymous();}public override async Task HandleAsync(StockReq r,CancellationToken ct)=>await Send.ResponseAsync(await s.Send(new F.CreateStock(r.ProductId,r.WarehouseId,r.Sku),ct),201,ct);}public sealed class GetStock(ISender s):Endpoint<StockReq,F.StockDto>{public override void Configure(){Get("/api/stock-items/{productId}/{warehouseId}");AllowAnonymous();}public override async Task HandleAsync(StockReq r,CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.GetStock(r.ProductId,r.WarehouseId),ct),ct);}
public sealed class Increase(ISender s):Endpoint<StockReq,F.StockDto>{public override void Configure(){Post("/api/stock-items/increase");AllowAnonymous();}public override async Task HandleAsync(StockReq r,CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.Increase(r.ProductId,r.WarehouseId,r.Quantity),ct),ct);}public sealed class Decrease(ISender s):Endpoint<StockReq,F.StockDto>{public override void Configure(){Post("/api/stock-items/decrease");AllowAnonymous();}public override async Task HandleAsync(StockReq r,CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.Decrease(r.ProductId,r.WarehouseId,r.Quantity),ct),ct);}
public sealed class Reserve(ISender s):Endpoint<ReserveReq,F.ReservationDto>{public override void Configure(){Post("/api/reservations");AllowAnonymous();}public override async Task HandleAsync(ReserveReq r,CancellationToken ct)=>await Send.ResponseAsync(await s.Send(new F.Reserve(r.ProductId,r.WarehouseId,r.OrderId,r.Quantity),ct),201,ct);}public sealed class Confirm(ISender s):Endpoint<ReserveReq>{public override void Configure(){Post("/api/reservations/{reservationId}/confirm");AllowAnonymous();}public override async Task HandleAsync(ReserveReq r,CancellationToken ct){await s.Send(new F.Confirm(r.ProductId,r.WarehouseId,r.ReservationId),ct);await Send.NoContentAsync(ct);}}public sealed class Release(ISender s):Endpoint<ReserveReq>{public override void Configure(){Post("/api/reservations/{reservationId}/release");AllowAnonymous();}public override async Task HandleAsync(ReserveReq r,CancellationToken ct){await s.Send(new F.Release(r.ProductId,r.WarehouseId,r.ReservationId),ct);await Send.NoContentAsync(ct);}}public sealed class GetReservation(ISender s):Endpoint<IdReq,F.ReservationDto>{public override void Configure(){Get("/api/reservations/{id}");AllowAnonymous();}public override async Task HandleAsync(IdReq r,CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.GetReservation(r.Id),ct),ct);}}

